#!/usr/bin/env python3
"""Aplica a organização por círculos sem substituir arquivos inteiros da base."""
import base64
from pathlib import Path
import subprocess
import sys

PATCH_B64 = """"""

def run(args, patch):
    return subprocess.run(args, input=patch, capture_output=True)

def main():
    patch = base64.b64decode(PATCH_B64)
    if not Path("src/App.jsx").exists():
        sys.exit("Execute na raiz do repositório conexia-agro.")
    if run(["git", "apply", "--reverse", "--check", "-"], patch).returncode == 0:
        print("Círculos já implementados. Nenhuma alteração necessária.")
        return
    check = run(["git", "apply", "--check", "-"], patch)
    if check.returncode:
        print(check.stderr.decode(), file=sys.stderr)
        sys.exit("A base mudou ou há arquivos parcialmente aplicados. Nenhum arquivo foi alterado. Revise antes de reaplicar.")
    result = run(["git", "apply", "-"], patch)
    if result.returncode:
        sys.exit(result.stderr.decode())
    print("Círculos aplicados. Execute npm ci, npm run build e node --test tests/networkCircles.test.js.")
    print("A estrutura de banco desta versão já foi aplicada no projeto Conexia - Iagro. Não execute o SQL novamente nessa base.")

if __name__ == "__main__":
    main()
